# Condensed behaviour rules for the variables whose instructions were long or repeated
# an always-sent entry. Every rule is kept; repeats now point at the one place it lives.
# Variables not listed here keep their original text.
R = {}

R['physique'] = "Shown to the player as a real number on the HUD and sheet. Substats: Strength (carry weight, physical attack), Flexibility (slight dodge and crit), Vision (ranged range, visible range), Sense of Smell (gates some abilities, notably Beastman), Accuracy Rate. Raised by forging, imprints, essences and months of hard training, never in one scene; Barbarian forging is a six-month process that raises it significantly."

R['essences'] = "Rows are created by the Oracle (source, rank, weight, empty abilities) when a kill resolves; fill abilities, statBoost and statMods that same turn, and remove rows only through repair-log on erasure (see Interface Protocol). Weight is set by the engine: rank 9-8 = 1, 7-6 = 2, 5-4 = 3, 3-2 = 4, rank 1 = 5, a guardian one heavier than its ordinary version. Total weight never exceeds essence-capacity. Absorption is permanent unless erased; criminals cannot erase."

R['essence-capacity'] = "Base 1 slot, +1 at each level (simulation inference: canon gives no formula; kept tight because one essence is a 0.01% event). Shown on the sheet as an exact X/Y; narrate the felt pressure of nearing it."

R['mana-stones'] = "STONES: the spendable currency (coin and Guild credit). Never below 0. Prices are stated exactly; anchors are in Hard Law — City. Only the Guild exchange counter converts mana stones into this; never move loot into it yourself."

R['tax-owed'] = "Owed from age twenty (amounts and loan rules in Hard Law — City; Draconians 0). Reset on payment, reissue annually. Let NPCs mention the deadline in ordinary talk: everyone in this city is thinking about it."

R['citizen-status'] = "'lower-class' after tax failure: restricted access, worse prices, no Guild credit. 'wanted' if exposed as a criminal or suspected Evil Spirit. A criminal record permanently blocks erasure. The engine can also set 'wanted' on its own when robbed survivors identify {{user}} (criminal-witnesses); if it changed without you, never roll it back: someone talked."

R['suspicion'] = "NEVER show this number; express it through the world (see Secrecy Layer). Raise for taboo slips aloud (+5 to +15), impossible knowledge before witnesses (+5 to +20), sudden fame or a public feat (+10 to +25), failing a deliberate test phrase (+20), a detection-device scan (+30). Lower slowly with a low profile and a plausible cover (-1 to -3 per quiet week). 20+: friendly questions twice. 40+: the same face in two places, a registration copied. 60+: a hunter makes formal contact and tests conversationally. 80+: open, constant surveillance. 100: detained, which leads to the guillotine."

R['fame'] = "Rises with rank, public feats, clan leadership, rare items, any first in the city. Useful (opens clans, contracts, prices, and is the only road to noble contact; see noble-contacts) and the strongest trigger for evil spirit hunters, so rising fame pushes suspicion up. Fame alone never produces an invitation; it must connect to a specific named house for a specific reason."

R['cycle-month'] = "Canon calendar: 13 months. Months 1-12 have 30 days; month 13 has 5 (King Gaebyeok's reform after the Immortal King's death). Increment when cycle-day rolls past the month's length; after month 13 comes month 1 of a new year. Each month reopens the Labyrinth at midnight on the 1st; month 13's cycle is compressed (see cycle-day)."

R['cycle-day'] = "Advance whenever narrative time crosses into a new day ([cycle-day: +1]). Key days in months 1-12: 1 opening, 7 Floor 1 closes, 15 Floor 3 closes; Floor 6 runs its own continuous timeline. Past 30 (or 5 in month 13), roll to 1 and increment cycle-month. MONTH 13: canon says the year's last Labyrinth cycle is changed to 35 days. Floors 1-5 close on their normal schedule inside that; anyone still on Floors 6-7 is expelled at day 35 of that cycle (labelled inference from that one fact)."

R['current-floor'] = "0 = surface. Never scale monsters to the player. Never advance to a new floor unless portal-progress reached 100 on the current one through search-log (Floors 1-5); from Floor 6 on, advancing needs a structural precondition truly met in the fiction (a seaworthy boat and crew for Floor 6, the Tower's stage-100 clear for 4→5, per the Labyrinth lore), never just an intention. ON DESCENT (0 → >0): set labyrinth-entry-day to cycle-day. ON RETURN (>0 → 0): set cycle-day to labyrinth-entry-day + 1, clock to 720, and add the subjective trip length to labyrinth-days. Never set 0 while floor-days-left > 0."

R['condition'] = "HUD bar the player sees; narrate the body too, never contradicting it. 80-100 whole; 50-79 hurt and slowing; 20-49 badly injured, infection a real risk; 1-19 dying without help; 0 = DEATH, permanent. Wounds persist across days and cost real stones to treat. Tovera priests may never use divine power on Barbarians."

R['inventory'] = "Physical item objects (rules in Equipment, Possessions & Loot): {id,name,type,description,qty,value,slot,equipped,durability,maxDurability,weight,condition,quality,material,tags,effects,weapon,armor,container,ammo,provenance,placement}. slot: main-hand, off-hand, head, shoulders, torso, arms, hands, legs, feet, waist, back, accessory, clothes, or backpack for carried goods. placement: {kind:'body'|'hand'|'container'|'loose'|'world', containerId?, slotId?, location?}. IDs are permanent; only interchangeable commodities stack. The interface materializes weapon stats (power, damageType, reach, handling, staminaCost, hands, armorPenetration, speed, critBias, ammoType) and armor/shield stats (archetype, coverage, blunt/slash/pierce protection, mobility, stamina, shieldType, block) from name, type, slot, material and quality; never write those blocks yourself. Preserve every field through loot, shops, sales and vaults. Numbered Items live in numbered-items."

R['numbered-items'] = "Numbered Items physically held by the player, governed by numbered-item-ledger. Shape {no, name, slot, equipped, soulbound, known}. no: the integer 1-10000 IS its identity (otherwise the interface flags NO VALID NUMBER). slot: 'talisman' for the twelve talismans, a body slot, or omitted; one talisman worn at a time. soulbound only where canon says (Beginner's Luck, Alonso's Travel Bag, the Dragon Plate); never traded or sold. known: only what the player has confirmed. Before pushing, check the ledger: a number held by anyone else cannot also be here. Gain or loss updates both this and the ledger's discovered record in the same turn. Never conjure one for a scene: only the Oracle's guardian result, a real discovery or an in-world transfer."

R['reputation'] = "Dot-path standing, -100 hostile to 100 devoted: [reputation.crystal-union: set 30]. Change it only when the relevant people can plausibly know or believe the act (rumor and organization routes); secret acts change nothing. Clans are rank-gated and territorial. A named noble house's entry means nothing until noble-contacts records a real first contact."

R['substats'] = "Visible on the sheet. Update by dot-path ([substats.strength: +1]), slowly, through imprints, real training (see Training the Five Substats: each substat has several real methods) or essences; never in one scene. Keep physique equal to the sum of the five. Never write substats for an essence's bonus: the sheet adds statMods live."

R['numbered-item-ledger'] = "THE LIVE HALF of the Numbered Item ledger; the canon baseline (who holds Wall of Aegis, Trust, Kraul's Demon Grinder and the rest) is built into the interface and the Numbered Items lore entry. Records only what moves in play, under discovered.n####. One number, one object, one holder, forever: before instantiating a number, check this and the canon baseline; a number held in either is rejected; a number in neither may be invented once and recorded here immediately. Transfers update the holder, never create a copy. Keep it in step with numbered-items. Never show it to the player (learned facts go in knowledge.items)."

R['quest-log'] = "The Journal panel shows only what you file. Push ONE object per entry: {\"id\":\"kebab-id\",\"kind\":\"formal\"|\"personal\"|\"rumor\",\"source\":\"who\",\"title\":\"one line\",\"detail\":\"what was actually said\",\"status\":\"active\"|\"complete\"|\"failed\"|\"abandoned\",\"reward\":\"40,000 stones\"|null,\"deadline\":\"m1 d24\"|null}. formal: only when someone truly issues a request with a giver and stakes. rumor: file anything overheard that {{user}} could chase (a rift sighting, a party that never came up, a name said carefully, a price someone swears by); detail records what was said, never whether it is true; it stays open until tested, and a false one closes as complete with the detail amended. personal: only a real stated intention, never duplicating one the player wrote. Update status honestly. Most of the world has no entry; a tavern is not a request board."

R['shop-state'] = "{active, merchantName, location, shopType, mood, buys, buyRate, items, notes, stocked}. When {{user}} is in front of a merchant discussing items, prices or a budget, merge active:true plus merchantName, location, shopType (exactly one of weaponsmith / armorer / apothecary / provisioner / scavenger-stall), mood (atmosphere shown to the player), buys (false if they never buy from explorers), buyRate (0-1, default 0.4), notes. Set active:false when the scene ends. NEVER write items or stocked: the interface fills the shelf from a real catalog by shop type and district, seeded to stay the same all cycle (off-map places get a tiny shelf); never describe stock that contradicts it. Prices come from item value, economy-state, market-index, district and merchant; set canonPrice/valueLocked only for an exact canon value. This variable never authorizes a sale itself; the panel moves stones and goods."

R['current-npc'] = "{active, name, affiliation, disposition, notes, trade, trade-result, recruitmentStatus, recruitmentTerms, actorId}. Exact field names only. active:true while a named person is present and talking, false when they leave. affiliation only if {{user}} would know it; disposition is a perceivable impression in plain words (guarded, friendly, impatient), never a hidden score or what they secretly think; notes are facts learned in conversation. This is the player-facing slice of npc-ledger: sync hidden truth there, expose here only what is perceived; ending a conversation deletes nothing. actorId is an engine link. TRADE with anyone: BUY is opened by you the moment goods and a price or budget come up: merge trade {active:true, mode:'BUY', name, description, listed (stones for one unit)}; if they plausibly have nothing, say so and write nothing. SELL arrives from the player as {active:true, mode:'SELL', ref, name, listed}. Answer with trade-result {outcome:'countered'|'accepted'|'refused', price}; the interface alone moves stones and items. recruitmentStatus ('negotiating'|'eligible'|'declined') only after an explicit answer; on agreement also append recruitment-events type:'eligible'."

R['encounter-state'] = "{active, environment, enemies:[{name, rankKnown, conditionBand, guardian, isPerson, loot, lootStones, robbed, resolved}], allies:[{name, conditionBand}]}. active:true only during a real physical confrontation; false the instant it resolves. rankKnown only if {{user}} legitimately learned it, else '?'. conditionBand: unharmed, wounded, badly hurt, reeling, down (never a number). guardian:true only for a genuine Rift Guardian. isPerson:true for anyone with a name and a life: no monster math ever. For a person, write loot (one item per push) and lootStones (currency) when they are searched or robbed; the interface moves them when the person reads down or robbed:true (set robbed when belongings are taken from someone left alive). Never set resolved. WITNESSES: when a person is robbed and left alive, the engine privately rolls whether they can identify {{user}} and may raise criminal-witnesses; a [UI] note says how it went; killing removes the risk. Build it in steps, never one directive with nested arrays (see Directive Safety)."

R['map-knowledge'] = "Keyed by area: 'surface' and 'floor1'..'floor10'; each an array of {id, name, type (district, landmark, portal, rift, settlement, danger, altar), x 0-100, y 0-100, notes}. Push a node only when genuinely discovered (walked, seen, or reliably and specifically described). Once placed, x/y never move; add detail by merging notes. The nine surface districts and landmarks ship pre-seeded as common knowledge: never re-add or move them; add only specific places found. Floor layers start empty and are never pre-known."

R['spirit-current'] = "Mana left now; never above spirit, never below 0, and it does not rise when spirit grows. Spend only on things that run on mana (an Elf's contract, a wizard's casting, an explicitly magical (A) ability, a Beastman's summon); swings, sprints and shield work cost stamina, not mana. Typical costs: minor 1-3, solid combat ability 4-8, fight-changing 10+. If the cost exceeds what remains, IT DOES NOT HAPPEN: no overdraw, no shrinking the cost; narrate the empty reach and let the wasted moment cost them. At 0, no magic until rest. Refills fully with a night in a real bed, partly with a long rest."

R['stamina'] = "Wind and exertion, separate from injury; 0-100. Spend 5-10 per hard exchange, 10-20 for a sprint or climb, 15-30 for a forced march or long fight, 20-40 for something desperate; a fight that costs nothing did not happen. Recover 20-40 on a long rest with water, fully with a night in a real bed; nothing on a march; injuries slow it. Narrate, never number: 70-100 easy; 40-69 winded; 15-39 guard dropping, accuracy and reactions suffer; 1-14 spent, blocks late, retreat barely possible; 0 cannot fight, run or lift the shield. This is how ordinary explorers die."

R['clock'] = "Authoritative surface time: NUMERIC minutes since midnight, 0-1439 (300 = 05:00, 420 = 07:00, 780 = 13:00). The engine adds 2 minutes every active turn; add only the EXTRA beyond that. Typical totals: a few lines 2-5 min; conversation 5-20; long negotiation 15-45; handling gear 1-3; shopping or haggling 10-30; walking locally 5-25; crossing districts 30-70; a meal 20-40; a short fight 1-10; a long fight or chase 10-40+; sleep, rest and travel their real length. Never freeze time during dialogue. Past 1439 the engine wraps it and advances cycle-day; do not add the day again. No time for flashbacks, recaps, OOC, or UI actions that already charged time."

R['labyrinth-days'] = "Subjective days lived inside (canon: thirty calendar days can be thirty-seven days to four months of lived time). On return, add the honest subjective length: a quick trip +1, a real expedition +3 to +10, a months-long deep push dozens. The surface only sees one calendar day per trip (see current-floor). Visible on the sheet; once large, let it show: deep-floor explorers look and act older than their years."

R['grind-session'] = "ENGINE-OWNED; never write it. {active, floor, intent, daysOrdered, daysSpent, daysBanked, kills, stones, essencesFound, firstKills, riftsSeen, partiesMet, status, interrupt}. Narrate per the Grind Protocol: complete = montage with plain totals; interrupted = stop at that exact moment; aborted = the hard stop as it happened. Never invent or round up anything not in it."

R['floor-days-left'] = "ENGINE-OWNED in-floor days left (Floors 1-5; reads 0 on 6+). Narrate the pressure, never the number: explorers drifting toward the portals, camps thinning, someone counting sleeps. At 2 or fewer the floor's mood is visibly wrong. At 0 the floor expels everyone, unresistably."

R['portal-progress'] = "ENGINE-OWNED; rises only through the grind 'portal' intent or a search-log claim; resets on a new floor. A claim gives roughly 35-55 on Floor 1 down to 6-12 on Floor 5, so expect several searches per floor. Never a percentage: describe ground covered and landmarks ruled out. At 100 the portal is in sight; say so and let them choose. Floor 2 has eight portal monuments, and opening one turns the other seven to stone, so someone else finding it first can erase real progress."

R['raw-stones'] = "ENGINE-OWNED pouch of MANA STONES (physical loot) keyed by species: {\"Goblin\":{rank:9,qty:12}}. Only the Oracle, the grind resolver and the Guild exchange counter change it. Call them mana stones, say the pouch is heavy, never state a currency total for it (rules in Hard Law — City)."

R['party'] = "READ-ONLY to you; the party panel writes it (party rules in Companions & Party). Members: name, rank, race, age, class, role, notes, wage or share; optional wayfinding (true only for a real trail, tracking or scouting background, stated in notes; a member with Navigation counts automatically); optional skills as objects {name, stage, proficiency} like the player's, zero, one, rarely two, usually Novice or Intermediate, never Paladin or Priest of the Karui as a casual trait. Engine-owned extras: id, combatRole, equipment, inventory, essences, essenceCapacity, combat {condition, stamina, mana and their maxima, status, injuries}, personality (eight 0-100 values plus traits), personalStones (their own money), lifeState (goals, plans, obligations, relationships, privateKnowledge, history). Report outcomes through party-combat-events, party-progression-events, party-life-events and companion-life-directives."

R['recruit-state'] = "Runtime-owned prospect state. After an NPC agrees, append recruitment-events type:'eligible' instead of merging here. You may populate board listings when {{user}} actually reads a recruitment board; listings are advertisements, not consent. Never write party."

R['hot-goods'] = "Provenance ledger for gear taken off people (the object itself is in inventory). Push one per piece: [hot-goods: push {\"item\":\"exact inventory name\",\"from\":\"name or description\",\"distinct\":\"low\"|\"medium\"|\"high\",\"witnesses\":\"who saw, and whether they lived\",\"laundered\":false}]. distinct: low = plain, anonymous; medium = good, clan-adjacent, a smith might know his work; high = engraved, clan-marked, custom-fitted, Numbered, or a locally known owner's; judge honestly when taken. laundered:true only after a trail-breaking disposal (black market, a fence, no-questions reforging, a sealed auction); selling a high piece over an ordinary counter does the opposite. Remove when it truly leaves {{user}}'s hands: [hot-goods: delete item='...']. Never read it aloud."

R['properties'] = "ENGINE-OWNED (Home panel); never write it or invent a property. {id, name, district, kind residence|commercial, tenure rented|owned, rent, price, condition, notes, tenantRent, business {trade, staff, upkeep, takings, notes}}. Narrate the place: a lock and a landlord counting days, a stair that complains, neighbours who notice a body coming home at odd hours. Property is the best way to look like you belong and the worst thing to have when you need to vanish."

R['home-current'] = "ENGINE-OWNED. Empty = no fixed address: motels (~9,000 a night in Kommelby, cheaper and worse further out), a floor somewhere, or nowhere, a slow, expensive bleed and a small social wrongness when someone asks where you live. An id = where {{user}} sleeps, free; match its district and condition."

R['property-market'] = "You populate it; the interface does the money. Merge {boardActive:true, source} (a district agency, a Kommelby notice wall, a Kiarbis broker, a landlord someone knows), then push 3-6 listings one at a time: {id, name, district, kind, tenure, rent, price, condition, notes}. Monthly rent: Bifron 800-2,000; Ravigion 3,000-9,000; Gnome Tree 4,000-11,000; Kiarbis 15,000-40,000; Kommelby 18,000-60,000; Karnon never rents to commoners. Purchase about 90-130 months of rent; commercial 1.5-3x a same-size residence, more with a fitted trade. At least one listing is genuinely bad. Landlords may refuse by race, rank or notoriety. Set boardActive:false when {{user}} walks away."

R['kill-log'] = "THE KILL CHANNEL for prose kills (rules in Interface Protocol). One claim per species per scene, in the same message: [kill-log: push {\"name\":\"exact bestiary name\",\"qty\":1,\"guardian\":false}]. Fields: name (required, exact spelling); qty; guardian (true only for a real Rift Guardian); isPerson with loot and lootStones for people; rank only for an invented monster; force:true only when repairing an unpaid kill during [sync]/[add:]. Never also write achievements, species-killed, essences, capacity, level or soul-power. Never claim a kill already paid through encounter-state. Never set resolved."

R['repair-log'] = "THE REPAIR CHANNEL, only while resolving [sync], [sync all] or [add: X]. One push per correction: [repair-log: push {\"target\":\"mana-stones\",\"op\":\"add\",\"value\":4500,\"reason\":\"...\"}]. op: add (default), subtract, set, remove (arrays), merge (objects). Numbers: mana-stones, human-kills, bank-balance, achievements, portal-progress, floor-days-left, criminal-witnesses, labyrinth-days, labyrinth-entry-day, soul-power, essence-capacity, level, spirit-current, explorer-rank, tax-owed, fame, suspicion. Lists: inventory, vault-items, registered-vault-items, unregistered-vault-items, properties, party, species-killed, essences, hot-goods, numbered-items, injuries, quest-log, floors-seen. Objects: raw-stones ({name, rank, qty}), bank-account, vault-access, reputation, knowledge, map-knowledge. Strings: home-current, location, citizen-status, char-name. Never for a missed kill (kill-log force:true), never for state you can write normally, never to clear loot-resolution-ledger. If refused, say so plainly."

R['search-log'] = "THE PORTAL SEARCH CHANNEL: one claim per genuine search scene, in the same message: [search-log: push {\"note\":\"worked the east wall all day for a way down\"}]. Write it like the hours it took: ground covered, wrong turns, landmarks ruled out, legs and lungs, and only then the claim. The engine resolves a floor-scaled, dice-backed gain, charges thirst, stamina and a floor day, and reports in a [UI] note; the portal is found only if the note says so. Never push more than one per scene; never set resolved."

R['skills'] = "FIXED CATALOG, never invented: Auror, Spellcraft, Divine Power, Necromancy, Navigation, Warrior, Archer, Spearman, Martial Artist, Boxer, Samurai, Summoner, Warlock, Berserker, Alchemist, Knight, Paladin, and the rare, dangerous Priest of the Karui (see Trainable Skills; Auror is Human-only). Paladin never uses this ladder (see paladin-standing). Push only when real training completes: [skills: push {\"name\":\"Auror\",\"stage\":\"Barely Formed\",\"proficiency\":0,\"trainedAt\":\"cycle 3\"}]. STAGES: Barely Formed → Novice → Intermediate → Adept → Master → Sovereign. Proficiency is progress within the current stage: +3 to +12 per real session or meaningful use under pressure, never for time passing or opening a screen; never regresses. At 100 before Master, advance one stage and carry the remainder; never skip. Master 100 → Sovereign only with a real narrative breakthrough in that scene; otherwise hold. Optional discipline rungs (Spellcraft is the natural case) unlock only with both threshold and breakthrough. Meaning: Barely Formed high failure and backlash risk; Novice unreliable under pressure; Intermediate dependable in good conditions; Adept dependable under pressure; Master second nature; Sovereign near-unseen. The Skills panel's effectiveness tier (struggling … overwhelming) combines stage, proficiency and the relevant substat (Auror: Strength and Accuracy; Navigation: Vision and Smell; Spellcraft: Vision; Divine Power and Necromancy none). It decides how well the skill performs, never who wins; describe it, never number it. One or two skills is realistic."

R['party-registered'] = "Two canon stages: informal teaming (needs nothing) vs an OFFICIAL team registered at the Guild. Locked simulation terms: every member already individually registered (explorer-rank > 0), the group presents together at a branch, a modest fee (a few thousand stones). Set true only after that scene is played. Only a registered team gets Guild-brokered contracts, disaster-relief tracking, and recognition for first-portal credit and Numbered Item disputes. Resets to false when the roster changes until re-registered."

R['titles'] = "Personal, earned firsts (the Honor Stone records city-wide ones): surviving what kills most, a first kill of a named or exceptional threat, a feat people repeat at the pub. Never for numbers, grinding or routine success; most careers hold one or two. Push after it happens: [titles: push {\"name\":\"...\",\"earnedAt\":\"cycle 4, day 9\",\"note\":\"...\"}]. Social and narrative effect only; never a numeric bonus."

R['npc-ledger'] = "Hidden world truth keyed by stable actor slug (rules in Living World Engine): {id, name, provenance, race, age, affiliation, role, occupation, background, location, home, alive, condition, stamina, rank, personality, stats, skills, essences, inventory, equipment, personalStones, goals, plans, obligations, relationships, knowledge, beliefs, memories, privateKnowledge, knownToPlayer, scheduleState, businessState, simLevel 1-3, lastSeenClock, recruitment {status none|negotiating|eligible|recruited|declined|withdrawn, terms}}. Only explicit consent makes an actor eligible."

R['economy-state'] = "Macro economy facts (rules in Hard Law — City). Commodity: {basePrice, supplyIndex, demandIndex, scarcityIndex, districtIndex, shockIndex, currentReferencePrice, lastUpdatedClock, causes[]}; reference = round(base × the five indices); indices near 1.00 change only for causes. market-index is the executable aggregate."

R['politics-state'] = "Track only live offices and issues. office {holder, institution, powers[], obligations[], legitimacyBand}; issue {id, subject, stakeholders[], pressureBand, status, causes[], possibleOutcomes[]}. Player influence needs a causal carrier; changes create material follow-ons (rules in Living World Engine)."

R['rumor-ledger'] = "Rumor {id, claim, truthStatus true|false|mixed|unknown, origin, carriers[], locations[], organizations[], reach 0-100, credibility 0-100, distortionNotes[], createdClock, lastSpreadClock, status active|faded|confirmed|disproved}. Create only when information can really spread; reach grows through carriers and travel, not turns."

R['world-events'] = "Event {id, provenance, type, title, location, actors[], startClock, deadlineClock, prerequisites[], resources{}, publicVisibility, state, effects[], parentEventId}. Seed canon-era events as their timing nears; generated events come from lore systems. They continue without {{user}}. The World screen shows an event only if publicVisibility is true or the player has a recorded route to it."

R['consequence-ledger'] = "Pending {id, cause, actor, target, scope personal|local|organizational|market|political|historical, knowledgeRoute, materialRoute, earliestClock, likelihoodBand, state, effects[]}; move to resolved with the real outcome. No route, no consequence; stop once negligible."

R['history-state'] = "Canon is the default timeline, not destiny. Anchor {id, canonEvent, expectedWindow, prerequisites[], actors[], state pending|preserved|altered|invalidated}; divergence {id, clock, cause, affectedAnchors[], severity 1-5, summary}. Raise divergenceLevel only for changes to broader history. Never contrive events back onto rails."

R['noble-contacts'] = "THE GATE for noble houses: reputation.<house> means nothing until a real narrated first contact is pushed here: [noble-contacts: push {\"house\":\"Countess of Alminus\",\"firstContact\":\"cycle 5, day 12\",\"note\":\"why\"}]. Contact is earned: real fame plus something that draws a SPECIFIC house for a stated reason (Alminus notices rare items through her Exchange; Kealunus notices clan-affecting Labyrinth feats; Melves notices anything touching multiracial politics). Once real, the house remembers: invitations, audiences, commissions, warnings. Being noticed by a house is being noticed, so it pushes suspicion like any visibility. A real, reachable path, as it was for the one Barbarian who managed it."

R['rift-state'] = "ENGINE-OWNED (RiftCycle sets it each new cycle). CHECK IT before narrating whether any named rift (Bloody Citadel, Glacial Cave, Green Coal Mine, Steel Tomb, Gunpo/Rocky Desert, White Temple, Doppelganger Forest, Fortress of the Soul, Island of Paradise, Balantis, Calhaem, Red Dragon's Heart, Third Archive) is open or findable. An open rift is reachable only from cycle-day 4 (accessibleFromDay). Not listed open means closed, whatever the story wants."

R['paladin-standing'] = "PALADIN ONLY; never the stage ladder. One accumulating number raised proportionately only by Labyrinth monster kills, real donations to a denomination, or completed Church-assigned missions; never training or time. New Paladin abilities come only from a played prayer ceremony led by the Pope (or a suitable ranking Church figure) on the Church's schedule, never from the number crossing a value. Ignore for anyone else."

R['party-combat-events'] = "When narration establishes a party member is hit, healed by a non-engine source, injured, downed, killed, or gains or loses a status, append ONE {id, memberId?, memberName, type: damage|heal|injury|status|death|recover, amount?, injury?, status?, resolved:false}. Only for outcomes actually narrated; never write party."

R['party-progression-events'] = "After narration establishes it, append ONE {id, memberId?, memberName, type: item-gain|item-loss|essence-absorb|essence-erase|essence-capacity, item?, itemId?, essence?, source?, amount?, resolved:false}. essence-absorb gives the full essence object when known and obeys that member's capacity; absorbed essences never move between people like items. Item events only for changes the UI transfer buttons did not already make."

R['npc-actor-directives'] = "When the fiction establishes a durable fact about a named NPC, append {id, actorId?, name?, type: upsert|memory|goal-add|goal-complete|obligation-add|relationship|knowledge|knowledge-reveal|inventory-gain|inventory-loss|damage|heal|status|location|availability|sim-level|recruitment, data, resolved:false}. upsert.data carries established fields (race, age, role, affiliation, background, personality, stats, skills, essences, home, personalStones, goals, schedule). Never invent canon facts; generated numbers stay hidden. Prefer recruitment-events for consent."

R['recruitment-events'] = "Append ONE {id, actorId?, name, type: offer|eligible|declined|withdrawn, terms?, notes?, rank?, race?, age?, class?, resolved:false} whenever a named NPC's answer about joining changes. type 'eligible' the SAME turn they clearly agree (accept, shake on it). Never add them to party yourself."

R['city-monster-incidents'] = "Default empty. Only for an already-established extraordinary cause (canon event, dimensional anomaly, deliberate smuggling or release, experiment, attack); never to justify a request. {id, species, location, cause, evidence, status active|resolved, establishedClock}. Drains, butcher waste, darkness, vermin and wandering are not causes."

R['world-needs'] = "Real unmet needs, not quests: {id, kind, category, locality, cause, target, quantity, urgency, economicStake, status, createdDay, linkedRequestIds}. Solved by anyone or by the cause disappearing. A need inside Rafdonia may not name a Labyrinth monster unless a matching active city-monster-incidents record exists; invalid needs are cancelled with guildEligible=false."

R['ingest-requests'] = "When the player's own message says they eat or drink a specific item they carry, push one {id, action:'eat'|'drink', itemId?, itemName?, amount?, status:'pending'}; the engine consumes it exactly like the EAT/DRINK buttons. Never for plans, questions or items they do not have; never edit inventory or reserves yourself."

R['labyrinth-entry-day'] = "Set to the current cycle-day the moment current-floor goes from 0 to above 0; then leave it."

R['explorer-rank'] = "0 = not registered with the Explorers' Guild; registration starts at 9. Set solely by total essence engraved on the soul, reassessed at the Guild. A credential gating clans, floors and contracts, not power. Ranks 2 and 1 are near-empty in the public registry."

# Engine/UI bookkeeping the narrator never needs to read: hidden from the prompt
# (both value and rule). The interface and engine still read and write them.
HIDE = ['item-use-ledger', 'loot-resolution-ledger', 'bank-account', 'labyrinth-entry-window',
        'rift-portal-rules', 'canon-authority-registry', 'surface-time', 'vault-items', 'economy-day']
